// Slot jam: 05.30 s/d 20.00, tiap 30 menit
function buildTimeSlots() {
  const slots = [];
  let h = 5, m = 30;
  while (h < 20 || (h === 20 && m === 0)) {
    slots.push(`${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}`);
    m += 30;
    if (m >= 60) { m = 0; h += 1; }
  }
  return slots;
}
const TIME_SLOTS = buildTimeSlots();

